-- The two checklists published on 2026-10-16: When Your Pet Is Ill (Pets) and
-- The Hour Before an Interview (Confidence).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-16`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-your-pet-is-ill', 'When Your Pet Is Ill', 'For the weeks an animal you love is sick and the decisions keep coming. It keeps the vet''s answers, the costs and the medication times in one place, and treats the worry as real rather than something to apologize for.', 'Pets', '["Write down what you have noticed, with dates — the vet asks questions you cannot answer from memory.", "Ask what the next week is likely to look like — a picture of what is coming beats guessing between visits.", "Get the cost of each option in writing — money is part of this decision and pretending otherwise helps nobody.", "Put the medication times on a timer — dosing a frightened animal is hard enough without also remembering.", "Set up one room so nothing is a climb — water, bed and litter or pads within a few steps.", "Tell one person who will take it seriously — people who shrug at pet news are not the ones to tell.", "Keep one piece of your own routine — the walk, the meal, the bedtime; your days still need edges.", "Write down what a good day looks like for them — the mark is easier to set now than in a waiting room.", "Let yourself feel it before anything happens — dreading the loss is already a kind of grieving."]'::jsonb, 'weekly', array['Caregiving', 'Worry']::text[], 1, '2026-10-16T16:00:00+00:00'::timestamptz),
  ('the-hour-before-an-interview', 'The Hour Before an Interview', 'For the hour before an interview, when the preparation is done and the nerves arrive anyway. It settles the practical things early, puts three stories within reach, and gives you something to say if your mind goes blank.', 'Confidence', '["Be somewhere nearby twenty minutes early — arriving in a rush is a feeling you then have to talk through.", "Read your own application once, not five times — they will ask about what you wrote, not what you crammed.", "Have three stories ready rather than a script — a story you can tell survives a question you did not expect.", "Write down one question you actually want answered — it is often the part they remember afterward.", "Drink water and eat something small — a dry mouth and an empty stomach both read as nerves.", "Put your phone away before you walk in — the last thing you read sets the mood you arrive in.", "Breathe out slowly for a count of six — a long exhale settles the body faster than a pep talk.", "Decide now what you will say if you blank — “Can I come back to that?” is a complete answer.", "Plan the first thing you do when it ends — a coffee or a walk gives the rest of the day somewhere to land."]'::jsonb, 'as needed', array['Work', 'Anxiety']::text[], 1, '2026-10-16T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
